function GMHelper:changeRoomSetting(type, status)
    GMHelper:openInput({ "" }, function(userId)
        local data = {
            userId = tonumber(userId),
            permissionType = 1,
            settingList = {
                {
                    id = type,
                    switch = status
                }
            }
        }
        CEvents.GameActionTriggerEvent:invoke(CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_UPDATE_PLAYER_PERM_SETTING, json.encode(data))
    end)
end

function GMHelper:customGameUserVersion()
    local player = PlayerManager:getClientPlayer()
    local data = tostring(player.userId)
    CEvents.GameActionTriggerEvent:invoke(CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_USER_ENTER, data)
end

function GMHelper:exchangeowner()
    GMHelper:openInput({ "" }, 
    function(userId)
        local data = tostring(userId)
        CEvents.GameActionTriggerEvent:invoke(CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_EXCHANGE_OWNER, data)
    end)
end

