function GMHelper:openTaskPicture()
    GUIManager:hideWindowByName("PlayerInventory.json")
    GUIManager:hideWindowByName("Menu.json")
    GUIManager:hideWindowByName("Chat.json")
    RootGuiLayout.Instance():showMainControl()
    UIHelper.showGameGUILayout("GUITakePictureMain")
    local player = PlayerManager:getClientPlayer()
    player:sendPacket({
        pid = "takePictureStatus",
        userId = player.userId,
        status = true
    })
end

function GMHelper:showClientRole()
    local role = PlayerManager:getClientPlayer().permissionRole or Define.CustomGamePermissionRole.Member
    GMHelper:openInput({ "role:" .. role }, function(userId)

    end)
end

