function GMHelper:setUGCMarkerSetting()
    GMHelper:openInput({ "" }, function(str)
        local split = StringUtil.split(str, ",")
        local data = {
            teamId = tonumber(split[1] or 1),
            itemId = tonumber(split[2] or 1),
            meta = tonumber(split[3] or 0)
        }
        CEvents.GameActionTriggerEvent:invoke(Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_SET_TEAM_MARKER, json.encode(data))
    end)
end

function GMHelper:crUGCMarkerSetting()
