end

function GMHelper:UGCTeleport()
    GMHelper:openInput({ "" }, function(str)
        local split = StringUtil.split(str, ",")
        local data = {
            pos = {
                x = tonumber(split[1] or 1),
                y = tonumber(split[2] or 1),
                z = tonumber(split[3] or 0)
            }
        }
        CEvents.GameActionTriggerEvent:invoke(Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_TELEPORT, json.encode(data))
    end)
end

function GMHelper:getItemUrlNames()
	local list = {};
    local itemUrlConfig = FileUtil.getGameConfigFromCsv("ItemUrl.csv", 1)
    for i, v in pairs(itemUrlConfig) do
        local item = {
			id = tonumber(v.id),
			itemId = tonumber(v.ItemId),
			meta = tonumber(v.subItemId),
            fileName = v.IconUrl,
			type = tonumber(v.type),
			subtype = tonumber(v.subtype)
        }
        table.insert(list, item)
    end
	table.sort(list, function(a, b)
		return a.id < b.id
	end)
    local log = "\n"
    log = log .. "============================== ItemUrl.csv\n"
    for _, item in ipairs(list) do
        local name = LanguageManager.Instance():getItemName(item.itemId, item.meta)
        log = log .. string.format("%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
            tostring(item.id),
            tostring(item.itemId),
            tostring(item.meta),
            tostring(item.fileName),
            tostring(item.type),
            tostring(item.subtype),
            name or "")
    end
    print(log)

    list = {}
    itemUrlConfig = FileUtil.getGameConfigFromCsv("CreativeBlock.csv", 1)
    for i, v in pairs(itemUrlConfig) do
        local item = {
            id = tonumber(v.Id),
            itemId = tonumber(v.ItemId),
            meta = tonumber(v.subItemId),
            filter = v.filter
        }
        table.insert(list, item)
    end
	table.sort(list, function(a, b)
		return a.id < b.id
	end)
    log = "\n"
    log = log .. "============================== CreativeBlock.csv\n"
    for _, item in ipairs(list) do
        local name = LanguageManager.Instance():getItemName(item.itemId, item.meta)
        log = log .. string.format("%s\t%s\t%s\t%s\t%s\n",
            tostring(item.id),
            tostring(item.itemId),
            tostring(item.meta),
            tostring(item.filter),
            name or "")
    end
    print(log)

    list = {}
    itemUrlConfig = FileUtil.getGameConfigFromCsv("CreativeItem.csv", 1)
    for i, v in pairs(itemUrlConfig) do
        local item = {
            id = tonumber(v.Id),
            itemId = tonumber(v.ItemId),
            meta = tonumber(v.subItemId),
            filter = v.filter
        }
        table.insert(list, item)
    end
	table.sort(list, function(a, b)
		return a.id < b.id
	end)
    log = "\n"
    log = log .. "============================== CreativeItem.csv\n"
    for _, item in ipairs(list) do
        local name = LanguageManager.Instance():getItemName(item.itemId, item.meta)
        log = log .. string.format("%s\t%s\t%s\t%s\t%s\n",
            tostring(item.id),
            tostring(item.itemId),
            tostring(item.meta),
            tostring(item.filter),
            name or "")
    end
    print(log)
end

